{
  "name": "markdown-it-shiki-twoslash",
  "version": "1.1.12",
  "license": "MIT",
  "homepage": "https://github.com/shikijs/twoslash",
  "repository": {
    "url": "https://github.com/shikijs/twoslash.git",
    "directory": "packages/markdown-it-shiki-twoslash",
    "type": "git"
  },
  "bugs": {
    "url": "https://github.com/shikijs/twoslash/issues"
  },
  "description": "A markdown-it plugin for Shiki with Twoslash code samples",
  "author": "Orta Therox",
  "main": "./dist/index.js",
  "type": "module",
  "typings": "./dist/index.d.ts",
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "esbuild src/index.ts --outfile=dist/index.js --target=node12 --platform=node",
    "bootstrap": "npx tsc src/index.ts --declaration  --emitDeclarationOnly --outdir dist --esModuleInterop",
    "prepublishOnly": "npm run build; npm run bootstrap"
  },
  "dependencies": {
    "deasync": "^0.1.21",
    "remark-shiki-twoslash": "2.0.1"
  },
  "devDependencies": {
    "@types/deasync": "^0.1.1",
    "@types/jest": "^25.1.3",
    "@types/markdown-it": "^12.0.1",
    "markdown-it": "^12.0.6",
    "shiki": "0.9.3",
    "shiki-twoslash": "2.0.3",
    "tslib": "^1.10.0",
    "typescript": ">3"
  }
}

{
  "name": "vscode-twoslash",
  "displayName": "Twoslash in Markdown",
  "description": "Auto-complete for Twoslash code samples in your IDE",
  "publisher": "Orta",
  "version": "1.0.2",
  "repository": {
    "url": "https://github.com/shikijs/twoslash.git"
  },
  "engines": {
    "vscode": "^1.48.0"
  },
  "categories": [
    "Linters"
  ],
  "activationEvents": [
    "onLanguage:markdown"
  ],
  "contributes": {
  },
  "main": "./out/extension.js",
  "icon": "web/shiki-128.png",
  "scripts": {
    "vscode:prepublish": "yarn run compile",
    "compile": "tsc -p ./",
    "build": "tsc -p ./",
    "lint": "eslint src --ext ts",
    "watch": "tsc -watch -p ./",
    "pretest": "yarn run compile && yarn run lint",
    "test": "node ./out/test/runTest.js"
  },
  "devDependencies": {
    "@types/glob": "^7.1.3",
    "@types/lz-string": "^1.3.34",
    "@types/node": "^14.0.27",
    "@types/vscode": "^1.48.0",
    "@typescript-eslint/eslint-plugin": "^3.8.0",
    "@typescript-eslint/parser": "^3.8.0",
    "glob": "^7.1.6",
    "typescript": "^3.8.3"
  },
  "dependencies": {
    "@typescript/twoslash": "2.0.1",
    "gfm-code-blocks": "^1.0.0"
  }
}

